// kills, and only in a party window. Now every body that dies within KF_NEAR units of you puts a line in it, in a solo raid and in a party:
// your own kill as YOU killed (the party word is unchanged), anyone else's as the same words the floating label says, such as SKAV
// ELIMINATED or SENTRY DESTROYED. Nothing here moves a number: the death block calls killFeedNear once per body, as it makes the label.
// In a party the host tells the other window of a kill nobody in the party made (kf with seat -1); a party kill still goes through
// netEntGone. Four lines at most, as before.
var KF_NEAR=1100;
function feedLine(txt,me){
  if(!NET.feed) NET.feed=[];
  NET.feed.push({txt:String(txt),me:!!me,at:Date.now()});
  while(NET.feed.length>4) NET.feed.shift();
  return NET.feed.length;
}
function killFeedNear(e){
  var p=G&&G.player, who, txt;
  if(!G||G.sim||G.over||!p||!e||e.kind==='snitch') return false;
  if(typeof NET==='object'&&NET&&NET.on&&NET.role==='join') return false;   // the host tells a joined window
  if(Math.hypot(e.x-p.x,e.y-p.y)>KF_NEAR) return false;
  if(e.byPlayer||e.bySeat>0){
    if(NET.on) return false;   // a party: netEntGone puts it in the feed and tells the other window
